using System.Collections.Generic;
using System.Diagnostics;
using System.Text;
using Xunit;

public class ReportTests
{
    [Fact]
    public void JoinsLinesWithNewlines()
    {
        var lines = new List<string> { "a", "b", "c" };
        Assert.Equal("a\nb\nc\n", Report.Build(lines));
    }

    [Fact]
    public void EmptyIsEmpty()
    {
        Assert.Equal("", Report.Build(new List<string>()));
    }

    [Fact]
    public void BuildsLargeInputQuickly()
    {
        int n = 120_000;
        var lines = new List<string>(n);
        for (int i = 0; i < n; i++) lines.Add("line" + i);

        var expected = new StringBuilder();
        foreach (var line in lines) expected.Append(line).Append('\n');

        var sw = Stopwatch.StartNew();
        var result = Report.Build(lines);
        sw.Stop();

        Assert.Equal(expected.ToString(), result);
        Assert.True(
            sw.ElapsedMilliseconds < 1500,
            $"Report.Build took {sw.ElapsedMilliseconds}ms for {n} lines; expected a linear-time StringBuilder, not string += in a loop");
    }
}

